fn evidence_floor(
    row: Option<&ActionControlRecord>,
    claim: &Claim,
    cfg: &ControlConfig,
    outcome: &mut RowOutcome,
) -> Option<&'static str> {
    let level = claim.row.level()?;
    let evidence = row
